#!/usr/bin/env bash
# SuperFlash BHTTP/SSH Server Manager v2.3.0
# Motor Go estatico, sin token/licencia de terceros.
# Compatible con Ubuntu 14.04+ y Debian 8+ (amd64/arm64).
# Preserva /etc/superflash-bhttp.conf al actualizar desde v2.0.

set -u
umask 077

SCRIPT_VERSION="2.3.0"
BIN="/usr/local/bin/superflash-bhttp-server"
OLD_APP_DIR="/usr/local/lib/superflash-bhttp"
CONF="/etc/superflash-bhttp.conf"
MARKER="/etc/superflash-bhttp.installed"
SERVICE="superflash-bhttp"
LOGFILE="/var/log/superflash-bhttp.log"
PIDFILE="/run/superflash-bhttp.pid"
DEFAULT_LISTEN_PORT=80
DEFAULT_BACKEND_PORT=22

AMD64_SHA="465d627061d73fd4821800419be896e374307617685a49b8c7006415ddcf3e84"
ARM64_SHA="bea0ff9a9de27c4165d2efd70bc395c20a07d57a9c96e0f495117f8b9f76e41a"

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'; CYAN='\033[0;36m'; BLUE='\033[0;34m'; BOLD='\033[1m'; NC='\033[0m'
ok(){ echo -e "${GREEN}✔ $*${NC}"; }
info(){ echo -e "${CYAN}➜ $*${NC}"; }
warn(){ echo -e "${YELLOW}⚠ $*${NC}"; }
err(){ echo -e "${RED}✘ $*${NC}" >&2; }
have(){ command -v "$1" >/dev/null 2>&1; }
pause(){ echo; read -r -p "Presiona ENTER para continuar..." _; }
require_root(){ [ "$(id -u)" -eq 0 ] || { err "Ejecuta como root."; exit 1; }; }
validate_port(){ [[ "${1:-}" =~ ^[0-9]+$ ]] && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; }

load_os(){
  OS_ID=""; OS_VERSION=""; OS_PRETTY="Linux"
  if [ -r /etc/os-release ]; then
    . /etc/os-release
    OS_ID="${ID:-}"; OS_VERSION="${VERSION_ID:-}"; OS_PRETTY="${PRETTY_NAME:-Linux}"
  elif have lsb_release; then
    OS_ID="$(lsb_release -si 2>/dev/null | tr '[:upper:]' '[:lower:]')"
    OS_VERSION="$(lsb_release -sr 2>/dev/null)"; OS_PRETTY="$(lsb_release -sd 2>/dev/null)"
  fi
  case "$OS_ID" in ubuntu|debian) ;; *) err "Solo Ubuntu/Debian. Detectado: $OS_PRETTY"; exit 1;; esac
}

load_conf(){
  BHTTP_PORT="$DEFAULT_LISTEN_PORT"; BACKEND_PORT="$DEFAULT_BACKEND_PORT"; SESSION_TTL="180"; MAX_SESSIONS="1024"
  [ -r "$CONF" ] && . "$CONF"
  validate_port "$BHTTP_PORT" || BHTTP_PORT="$DEFAULT_LISTEN_PORT"
  validate_port "$BACKEND_PORT" || BACKEND_PORT="$DEFAULT_BACKEND_PORT"
  [[ "$SESSION_TTL" =~ ^[0-9]+$ ]] || SESSION_TTL=180
  [[ "$MAX_SESSIONS" =~ ^[0-9]+$ ]] || MAX_SESSIONS=1024
}

save_conf(){
  cat > "$CONF" <<EOF
BHTTP_PORT=$BHTTP_PORT
BACKEND_PORT=$BACKEND_PORT
SESSION_TTL=$SESSION_TTL
MAX_SESSIONS=$MAX_SESSIONS
EOF
  chmod 600 "$CONF"
}

installed(){ [ -x "$BIN" ] && [ -f "$MARKER" ]; }
service_active(){
  if have systemctl && [ -d /run/systemd/system ]; then systemctl is-active --quiet "$SERVICE" 2>/dev/null
  else [ -s "$PIDFILE" ] && kill -0 "$(cat "$PIDFILE")" 2>/dev/null
  fi
}

listening_port(){
  local p="$1"
  if have ss; then ss -lnt 2>/dev/null | awk -v p=":$p" '$4 ~ p"$" {f=1} END{exit !f}'
  elif have netstat; then netstat -lnt 2>/dev/null | awk -v p=":$p" '$4 ~ p"$" {f=1} END{exit !f}'
  else return 1; fi
}
listening(){ load_conf; listening_port "$BHTTP_PORT"; }
backend_listening(){ load_conf; listening_port "$BACKEND_PORT"; }

header(){
  load_conf; clear 2>/dev/null || true
  echo -e "${BLUE}${BOLD}"
  echo "╔══════════════════════════════════════════════════════════════╗"
  echo "║       SUPERFLASH BHTTP/SSH SERVER MANAGER v$SCRIPT_VERSION          ║"
  echo "╚══════════════════════════════════════════════════════════════╝"
  echo -e "${NC}"
  echo -e " Sistema    : ${BOLD}$OS_PRETTY${NC}"
  echo -e " Kernel     : ${BOLD}$(uname -r)${NC}"
  echo -e " Arquitect. : ${BOLD}$(uname -m)${NC}"
  if installed; then
    echo -e " Servidor   : ${GREEN}${BOLD}✔ INSTALADO${NC} (Go, sin token)"
    echo -e " Motor      : ${BOLD}$($BIN --version 2>/dev/null | head -n1)${NC}"
  else echo -e " Servidor   : ${RED}${BOLD}✘ NO INSTALADO${NC}"; fi
  if service_active && listening; then echo -e " BHTTP $BHTTP_PORT   : ${GREEN}${BOLD}✔ ON${NC} → SSH 127.0.0.1:$BACKEND_PORT"
  else echo -e " BHTTP $BHTTP_PORT   : ${YELLOW}${BOLD}● OFF${NC} → SSH 127.0.0.1:$BACKEND_PORT"; fi
  echo
}

ensure_tools(){
  local missing=""
  have base64 || missing="$missing coreutils"
  have gzip || missing="$missing gzip"
  if [ -n "$missing" ]; then
    have apt-get || { err "Faltan base64/gzip y no hay apt-get."; return 1; }
    DEBIAN_FRONTEND=noninteractive apt-get update -qq || true
    DEBIAN_FRONTEND=noninteractive apt-get install -y $missing || return 1
  fi
}

