  local arch data expected tmpgz tmpbin actual
  arch="$(uname -m)"
  tmpgz="$(mktemp /tmp/sfbhttp.XXXXXX.gz)"; tmpbin="$(mktemp /tmp/sfbhttp.XXXXXX.bin)"
